        lg = it["login"]
        if not isinstance(lg, str):
            sys.stderr.write("account login not string\n")
            sys.exit(2)
        if lg not in acc_by_login:
            acc_by_login[lg] = it
    if "next" in rr.links:
        nu = rr.links["next"]["url"]
        if not isinstance(nu, str):
            sys.stderr.write("next url not string\n")
