date_pat = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")
def parse_date(s):
  m = date_pat.match(s)
  if m is None:
    sys.stderr.write("bad date " + str(s) + "\n")
    sys.exit(2)
  y = int(m.group(1))
  mo = int(m.group(2))
  d = int(m.group(3))
  if mo < 1 or mo > 12:
    sys.stderr.write("bad date " + str(s) + "\n")
    sys.exit(2)
  leap = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
  if mo == 2:
    dim = 29 if leap else 28
  elif mo == 4 or mo == 6 or mo == 9 or mo == 11:
    dim = 30
  else:
    dim = 31
  if d < 1 or d > dim:
    sys.stderr.write("bad date " + str(s) + "\n")
    sys.exit(2)
  yy = y
  if mo <= 2:
    yy = y - 1
  if mo > 2:
    mp = mo - 3
  else:
    mp = mo + 9
  era = yy // 400
