pat = re.compile(r"^(\d{4})-(\d{2})-(\d{2})$")

def parse_ymd(s):
    mt = pat.match(s)
    if mt is None:
        fail("bad date: " + s)
    y = int(mt.group(1))
    m = int(mt.group(2))
    d = int(mt.group(3))
    if m < 1 or m > 12:
        fail("bad date: " + s)
    leap = 0
    if y % 400 == 0:
        leap = 1
    elif y % 100 == 0:
        leap = 0
    elif y % 4 == 0:
        leap = 1
    else:
        leap = 0
    ml = [31, 28 + leap, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    div = ml[m - 1]
    if d < 1 or d > div:
        fail("bad date: " + s)
    return y, m, d

def to_days(y, m, d):
    leap = 0
    if y % 400 == 0:
        leap = 1
    elif y % 100 == 0:
        leap = 0
    elif y % 4 == 0:
        leap = 1
    else:
        leap = 0
    ml = [31, 28 + leap, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    before_year = (y - 1) * 365 + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
    before_month = 0
    idx = 0
    while idx < m - 1:
        before_month = before_month + ml[idx]
        idx = idx + 1
    return before_year + before_month + (d - 1)

